cards.solution:
function buatNomor(n) {
  return `INV-${String(n).padStart(4, "0")}`;
}
function inisial(nama) {
  return nama.split(" ").map((k) => k[0].toUpperCase()).join("");
}
console.log(buatNomor(7));
console.log(buatNomor(123));
console.log(inisial("rina ayu putri"));
console.log(inisial("budi santoso"));
